function rs_def():array{return ['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'salaryMasters'=>[],'rentMasters'=>[],'salaryPeriods'=>[],'rentPeriods'=>[],'salaryAdvances'=>[],'rentPrepayments'=>[],'rentSalaryPayments'=>[]];}
function rs_read():array{tt_ensure_data_dir();if(!is_file(TT_RS_FILE))return rs_def();$h=fopen(TT_RS_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(rs_def(),$v):rs_def();}
function rs_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))rs_out(['ok'=>false,'error'=>'Salary and mill rent masters are available for TTI / BRM.'],422);return $v;}
function rs_date(string $v,string $label='Date'):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))rs_out(['ok'=>false,'error'=>$label.' is required.'],422);return $v;}
function rs_month(string $v):string{if(!preg_match('/^\d{4}-\d{2}$/',$v))rs_out(['ok'=>false,'error'=>'Select a valid month.'],422);return $v;}
function rs_amount(mixed $v,string $label='Amount',bool $allowZero=false):float{$n=round((float)$v,2);if($allowZero?$n<0:$n<=0)rs_out(['ok'=>false,'error'=>$label.' must be '.($allowZero?'zero or more':'greater than zero').'.'],422);return $n;}
function rs_month_start(string $m):string{return $m.'-01';}
function rs_month_end(string $m):string{return (new DateTimeImmutable($m.'-01'))->modify('last day of this month')->format('Y-m-d');}
function rs_next(array $items,string $p):string{$n=count($items)+1;do{$id=$p.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
