function rs_cat(string $v):string{$v=strtoupper(trim($v));$ok=['MILL_STAFF','OFFICE_STAFF','HOME_STAFF','DIRECTOR_REMUNERATION','HOME_MONTHLY_GIVE'];if(!in_array($v,$ok,true))rs_out(['ok'=>false,'error'=>'Select a valid salary category.'],422);return $v;}
