function rs_bank_balance(array $s,string $entity,string $bankId):float{$n=0;foreach((array)($s['journals']??[]) as $j){if(!is_array($j)||($j['status']??'')!=='Posted'||($j['entity']??'')!==$entity)continue;$jm=is_array($j['meta']??null)?$j['meta']:[];foreach((array)($j['lines']??[]) as $l){if(!is_array($l)||($l['account']??'')!=='1110')continue;$bid=(string)($l['bankAccountId']??$jm['bankAccountId']??'');if($bid===$bankId)$n+=(float)($l['debit']??0)-(float)($l['credit']??0);}}return round($n,2);}
