function rs_salary_row(array $s,array $m,string $month):array{$id=rs_period_id((string)$m['entity'],$month,(string)$m['id']);$p=is_array($s['salaryPeriods'][$id]??null)?$s['salaryPeriods'][$id]:null;$adv=0;foreach(rs_salary_advances_for($s,(string)$m['id'],$month) as $a)$adv+=(float)($a['amount']??0);return ['periodId'=>$id,'masterId'=>$m['id'],'name'=>$m['name'],'category'=>$m['category'],'categoryName'=>rs_cat_name((string)$m['category']),'month'=>$month,'gross'=>(float)$m['monthlyAmount'],'advancePaid'=>round($adv,2),'prepared'=>$p!==null,'appliedAdvance'=>(float)($p['appliedAdvance']??0),'paidAfterPrepare'=>(float)($p['paidAfterPrepare']??0),'outstanding'=>(float)($p['outstanding']??0),'productionCostEligible'=>(bool)($m['productionCostEligible']??false),'status'=>$p['status']??'Not Prepared'];}
